        de="Heldenwerte, Fähigkeiten, Erscheinungsdaten und die vollständige Balancehistorie stammen aus dem Overwatch Wiki, lizenziert unter CC BY-SA.",
        ja="ヒーローの数値、アビリティ、実装日、バランス調整の全履歴は Overwatch Wiki（CC BY-SA）から取得しています。",
        ko="영웅 수치, 기술, 출시일, 전체 밸런스 이력은 Overwatch Wiki(CC BY-SA)에서 가져옵니다.",
        zhCN="英雄数据、技能、发布日期和完整的平衡性历史来自 Overwatch Wiki，采用 CC BY-SA 许可。",
