        ru="Характеристики героев, способности, даты выхода и полная история баланса взяты из Overwatch Wiki, лицензия CC BY-SA.",
        uk="Характеристики героїв, здібності, дати виходу та повна історія балансу взяті з Overwatch Wiki, ліцензія CC BY-SA.",
        sv="Hjältestatistik, förmågor, släppdatum och hela balanshistoriken kommer från Overwatch Wiki, licensierad CC BY-SA.",
