        zhCN="燃烧中的目标",
        zhTW="燃燒中的目標",
        ru="Горящая цель",
        uk="Ціль у вогні",
        sv="Brinnande mål",
        ar="هدف مشتعل",
        pl="Płonący cel",
        tr="Yanan hedef",
