# The order Android expects, and the order a reader of the generated file can scan.
QUANTITIES = ("zero", "one", "two", "few", "many", "other")


def translatable_keys(xml: str) -> set[str]:
    """Keys a locale is expected to carry.

    A string marked `translatable="false"` is a proper name or a format fragment - the app's
    own name, a Twitch handle, the "t1" label on the tactics board. Counting those as
    missing made this script report a gap in every language that could never be closed.
    """
    plain = {
        m.group(1)
        for m in re.finditer(r'<string name="([^"]+)"([^>]*)>', xml)
        if 'translatable="false"' not in m.group(2)
    }
    # Plurals count too, or every language reads as short by however many there are.
    return plain | set(re.findall(r'<plurals name="([^"]+)"', xml))


def escape(value: str) -> str:
    """Android string escaping: apostrophes must be escaped, ampersands entity-encoded."""
    value = value.replace("&", "&amp;")
    value = re.sub(r"(?<!\\)'", r"\\'", value)
    return value


def write_locale(qualifier: str, key: str) -> int:
    lines = [
        '<?xml version="1.0" encoding="utf-8"?>',
        "<!-- Generated by tools/make_translations.py. Edit that file, not this one. -->",
        "<resources>",
    ]
    count = 0
    for name, langs in TRANSLATIONS.items():
        value = langs.get(key)
        if not value:
            continue
        lines.append(f'    <string name="{name}">{escape(value)}</string>')
        count += 1

    for name, langs in PLURALS.items():
        forms = langs.get(key)
        if not forms:
            continue
        lines.append(f'    <plurals name="{name}">')
        for quantity in QUANTITIES:
            text = forms.get(quantity)
            if text:
                lines.append(
                    f'        <item quantity="{quantity}">{escape(text)}</item>'
                )
        lines.append("    </plurals>")
        count += 1

    lines.append("</resources>")

    directory = RES / f"values-{qualifier}"
    directory.mkdir(parents=True, exist_ok=True)
    (directory / "strings.xml").write_text("\n".join(lines) + "\n", encoding="utf-8")
    return count


def main() -> int:
    english = (RES / "values" / "strings.xml").read_text(encoding="utf-8")
    total_keys = len(translatable_keys(english))

    for qualifier, key in LOCALES.items():
        count = write_locale(qualifier, key)
        share = count / total_keys * 100
        print(f"  values-{qualifier:<8} {count:>3}/{total_keys} strings ({share:.0f}%)")

    print(f"\n{len(LOCALES)} locales generated; missing keys fall back to English.")

    # Italian is hand-written rather than generated, which means it is the one language that
    # can silently fall behind: a new string appears in English, lands in fourteen locales
    # from the table above, and is simply absent here. It went forty-five strings behind
    # before anyone noticed. Nothing is written for it - a machine translation of the
    # original language would be a step down - but it is counted out loud.
    hand_written = RES / "values-it" / "strings.xml"
    if hand_written.exists():
        italian = hand_written.read_text(encoding="utf-8")
        italian_keys = set(re.findall(r'<string name="([^"]+)"', italian)) | set(
            re.findall(r'<plurals name="([^"]+)"', italian)
        )
        missing = sorted(translatable_keys(english) - italian_keys)
        if missing:
            print(f"\nvalues-it is hand-written and is missing {len(missing)} strings:")
            for key in missing:
                print(f"    {key}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
